/// JSON 数字的无损数学值：符号、归一化有效数字、10 进指数。
/// 相同数值的不同写法（1、1.0、1e0、100e-2）归一化后完全一致。
#[derive(Debug, PartialEq, Eq)]
struct DecimalValue {
    negative: bool,
    digits: String,
    exponent: i64,
}

/// 无损十进制比较：直接解析数字词法，全程不经过 f64。
/// 依赖 serde_json 的 arbitrary_precision，Number 保留输入的原始词法。
fn number_eq(a: &Number, b: &Number) -> bool {
    decimal_value(a.as_str()) == decimal_value(b.as_str())
}

fn decimal_value(lexeme: &str) -> DecimalValue {
    let bytes = lexeme.as_bytes();
    let mut pos = 0;
    let negative = bytes.first() == Some(&b'-');
    if negative || bytes.first() == Some(&b'+') {
        pos = 1;
    }

    let mut digits = String::with_capacity(lexeme.len());
    let mut int_digits: Option<usize> = None;
    while pos < bytes.len() {
        match bytes[pos] {
            b'0'..=b'9' => digits.push(bytes[pos] as char),
            b'.' => int_digits = Some(digits.len()),
            b'e' | b'E' => {
                pos += 1;
                break;
            }
            _ => {}
        }
        pos += 1;
    }
    // 小数点后的位数用于把尾数折算成整数。
    let frac_digits = int_digits
        .map(|n| digits.len() as i64 - n as i64)
        .unwrap_or(0);

    let mut exponent: i64 = 0;
    if pos < bytes.len() {
        let exp_negative = bytes[pos] == b'-';
        if exp_negative || bytes[pos] == b'+' {
            pos += 1;
        }
        let mut raw: i64 = 0;
        while pos < bytes.len() {
            if let Some(d) = (bytes[pos] as char).to_digit(10) {
                raw = raw.saturating_mul(10).saturating_add(d as i64);
            }
            pos += 1;
        }
        exponent = if exp_negative { -raw } else { raw };
    }
    exponent = exponent.saturating_sub(frac_digits);

    // 去除前导零。
    let start = digits.bytes().position(|c| c != b'0').unwrap_or(digits.len());
    if start == digits.len() {
        // 0、-0、0.0、0e10 等一律归一化为正零。
        return DecimalValue {
            negative: false,
            digits: "0".to_owned(),
            exponent: 0,
        };
    }
    digits.replace_range(..start, "");

    // 去除末尾零并相应抬高指数，保持数值不变。
    let trailing = digits.len() - digits.trim_end_matches('0').len();
    digits.truncate(digits.len() - trailing);
    exponent = exponent.saturating_add(trailing as i64);

    DecimalValue {
        negative,
        digits,
        exponent,
    }
}

