            .unwrap(),
        )
        .unwrap_err();
        assert_eq!(err.status, 409);
        assert_eq!(err.path, "/changes/0/fields/0/old");

        // add 行整体值：等价值写法通过反向校验。
        apply_ok(serde_json::from_str(
            r#"{
                "rows": [{"id": "r", "values": {"n": 1}}],
                "changes": [{"id": "r", "op": "add", "value": {"n": 1.0}}],
                "direction": "reverse"
            }"#,
        )
        .unwrap());
    }
}

